"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student
from operator import attrgetter

def check_students(students: List[Student]) -> None:
    """Refuse an empty list or a student with no email."""
    if not students:
        raise ValueError("no students given")
    for student in students:
        if not student.email:
            name = student.display_name
            raise ValueError(f"no email for {name}")

def column_widths(
    students: List[Student]
) -> Tuple[int, int]:
    """Widest name and section, so the columns line up."""
    names = [item.display_name for item in students]
    sections = [item.section for item in students]
    return max(map(len, names)), max(map(len, sections))

def format_contact_row(
    item: Student, widths: Tuple[int, int]
) -> str:
    """One row: name, section, then email, padded."""
    name_width, section_width = widths
    name = item.display_name.ljust(name_width)
    section = item.section.ljust(section_width)
    return f"{name}  {section}  {item.email}"

def contact_rows(roster: Iterable[Student]) -> List[str]:
    """One text row per student, sorted by display name."""
    people = sorted(roster, key=attrgetter("display_name"))
    check_students(people)
    widths = column_widths(people)
    return [
        format_contact_row(item, widths) for item in people
    ]
